// Drive the exact stdio MCP command registered in OpenClaw (mcp.servers.gbrain).
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
const cfg = JSON.parse(readFileSync('/harness-state/openclaw/openclaw.json', 'utf8')).mcp.servers.gbrain;
const p = spawn(cfg.command, cfg.args, { env: { ...process.env, ...(cfg.env || {}) }, stdio: ['pipe', 'pipe', 'inherit'] });
let buf = '', id = 0; const waiters = {};
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue; try { const m = JSON.parse(line); if (m.id != null && waiters[m.id]) { waiters[m.id](m); delete waiters[m.id]; } } catch {} } });
const rpc = (method, params) => new Promise(r => { const i = ++id; waiters[i] = r; p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: i, method, params }) + '\n'); });
const call = async (name, args) => { const r = await rpc('tools/call', { name, arguments: args }); const t = r.result?.content?.map(c => c.text).join('\n') ?? JSON.stringify(r.error); return { isError: r.result?.isError, text: t }; };
console.log('config:', cfg.command, cfg.args.join(' '));
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tl = await rpc('tools/list', {});
console.log('tools:', tl.result.tools.map(t => t.name).join(', '));
for (const [name, args] of JSON.parse(process.argv[2])) {
  let r = await call(name, args);
  if (name === 'request_tools' ) {}
  console.log(`\n== ${name} ${JSON.stringify(args)}\n`, (r.isError ? 'ERROR ' : '') + r.text.slice(0, 1400));
}
p.kill();

